    h=hashlib.md5(json.dumps({'b':sorted(c['boards']),'n':{k:v.get('text') for k,v in c['notes'].items()}},sort_keys=True).encode()).hexdigest()
    snaps.append((os.path.getmtime(f),h,f,c))
snaps.sort()
seen=set(); uniq=[]
for s in snaps:
    if s[1] in seen: continue
    seen.add(s[1]); uniq.append(s)
prev=None
for t,h,f,c in uniq:
    print('\n=====',time.strftime('%m-%d %H:%M',time.localtime(t)),len(c['boards']),'boards',f.split('/')[3][:8])
    if prev:
        pb,pn=prev['boards'],prev['notes']
        add=sorted(set(c['boards'])-set(pb)); rem=sorted(set(pb)-set(c['boards']))
        if add: print('  + boards:',add)
        if rem: print('  - boards:',rem)
        for k,n in c['notes'].items():
